package com.example.Hospital.Management.System.services; import com.example.Hospital.Management.System.entities.*; import com.example.Hospital.Management.System.dtos.*; import com.example.Hospital.Management.System.repositories.*; import com.example.Hospital.Management.System.exceptions.*; import org.springframework.stereotype.Service; import java.util.*; @Service public class DepartmentService{private final DepartmentRepository r;private final HospitalRepository hr;public DepartmentService(DepartmentRepository r,HospitalRepository hr){this.r=r;this.hr=hr;} private Department find(Long id){return r.findById(id).filter(BaseClass::getIsActive).orElseThrow(()->new ResourceNotFoundException("Department not found"));} private DepartmentDTO dto(Department e){return DepartmentDTO.builder().id(e.getId()).name(e.getName()).description(e.getDescription()).hospitalId(e.getHospital().getId()).build();} private void apply(Department e,DepartmentDTO d){Hospital h=hr.findById(d.getHospitalId()).filter(BaseClass::getIsActive).orElseThrow(()->new ResourceNotFoundException("Hospital not found"));e.setName(d.getName());e.setDescription(d.getDescription());e.setHospital(h);} public DepartmentDTO create(DepartmentDTO d){Department e=new Department();apply(e,d);return dto(r.save(e));} public List<DepartmentDTO> all(){return r.findByIsActiveTrue().stream().map(this::dto).toList();} public DepartmentDTO get(Long id){return dto(find(id));} public DepartmentDTO update(Long id,DepartmentDTO d){Department e=find(id);apply(e,d);return dto(r.save(e));} public void delete(Long id){Department e=find(id);e.setIsActive(false);r.save(e);}}
